// Jarvis — guarda o app no celular para abrir e funcionar sem internet.
// Os cérebros (IA e voz) são guardados pelas próprias bibliotecas; aqui ficam o app e as bibliotecas.
const APP_VERSION = 28;                       // igual ao do index.html
const VERSION = 'jarvis-app-' + APP_VERSION;
const CORE = ['./', './index.html'];
const LIBS = [
  'https://cdn.jsdelivr.net/npm/@mlc-ai/web-llm@0.2.89/lib/index.js',
  'https://cdn.jsdelivr.net/npm/@huggingface/transformers@4.3.2/dist/transformers.min.js',
  'https://cdn.jsdelivr.net/npm/@mintplex-labs/piper-tts-web@1.0.5/+esm'
];
const CDN_HOSTS = ['cdn.jsdelivr.net'];

// Manifesto e ícones do app ficam aqui dentro (assim são só 2 arquivos)
const ICON_192 = '';
const ICON_512 = '';
const MANIFEST = {
  name: 'Jarvis', short_name: 'Jarvis', lang: 'pt-BR',
  description: 'Assistente pessoal por voz, com ou sem internet.',
  start_url: './', scope: './', display: 'standalone', orientation: 'portrait',
  background_color: '#071224', theme_color: '#071224',
  icons: [
    { src: 'jarvis-icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any maskable' },
    { src: 'jarvis-icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any maskable' }
  ]
};
const png = b64 => new Response(Uint8Array.from(atob(b64), c => c.charCodeAt(0)), { headers: { 'Content-Type': 'image/png', 'Cache-Control': 'max-age=31536000' } });

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(VERSION);
    await cache.addAll(CORE.map(u => new Request(u, { cache: 'reload' })));   // sempre a versão nova, nunca a do cache do navegador
    await Promise.allSettled(LIBS.map(u => cache.add(new Request(u, { mode: 'cors' }))));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    // Apaga só versões antigas do próprio app (nunca os cérebros baixados)
    for (const key of await caches.keys()) if (key.startsWith('jarvis-app-') && key !== VERSION) await caches.delete(key);
    await self.clients.claim();
  })());
});

async function networkFirst(request) {
  const cache = await caches.open(VERSION);
  // Busca a página nova (sem usar o cache do navegador). Se a internet estiver lenta, abre a guardada
  // e a nova continua baixando por trás: na próxima abertura ela já aparece.
  const net = fetch(request.url, { cache: 'no-cache', credentials: 'same-origin' }).then(res => {
    if (res && res.ok) cache.put(request, res.clone());
    return res;
  });
  try {
    return await Promise.race([net, new Promise((_, r) => setTimeout(() => r(new Error('timeout')), 4000))]);
  } catch (e) {
    net.catch(() => {});
    return (await cache.match(request, { ignoreSearch: true })) || (await cache.match('./index.html')) || Response.error();
  }
}

async function cacheFirst(request) {
  const cache = await caches.open(VERSION);
  const hit = await cache.match(request, { ignoreSearch: false });
  if (hit) return hit;
  const res = await fetch(request);
  if (res && (res.ok || res.type === 'opaque')) cache.put(request, res.clone());
  return res;
}

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin === self.location.origin) {
    if (url.pathname.endsWith('/jarvis-version')) { event.respondWith(new Response(String(APP_VERSION), { headers: { 'Content-Type': 'text/plain', 'Cache-Control': 'no-store' } })); return; }
    if (url.pathname.endsWith('/jarvis.webmanifest')) { event.respondWith(new Response(JSON.stringify(MANIFEST), { headers: { 'Content-Type': 'application/manifest+json' } })); return; }
    if (url.pathname.endsWith('/jarvis-icon-192.png')) { event.respondWith(png(ICON_192)); return; }
    if (url.pathname.endsWith('/jarvis-icon-512.png')) { event.respondWith(png(ICON_512)); return; }
    // Página principal: tenta a versão nova; sem internet, usa a guardada
    if (req.mode === 'navigate' || url.pathname.endsWith('/index.html') || url.pathname.endsWith('/')) { event.respondWith(networkFirst(req)); return; }
    event.respondWith(cacheFirst(req));
    return;
  }
  // Bibliotecas e o motor de voz offline: guarda na primeira vez e depois usa sem internet
  if (CDN_HOSTS.includes(url.hostname)) { event.respondWith(cacheFirst(req)); return; }
  // Pesquisas, clima, cotação e downloads de cérebro passam direto (as bibliotecas guardam os cérebros)
});
